using System.Collections.Generic;
using UnityEngine;

namespace ScrapTitan.Battle
{
    /// <summary>
    /// Finds the generated models and their named parts.
    ///
    /// Each asset is one FBX holding its parts as separate objects, each with its origin at
    /// the pivot its brief gives and positioned at its socket, which is exactly how a Kimi
    /// delivery arrives too. So nothing here knows whether a model was generated by
    /// tools/modelgen or delivered: swapping one for the other is a file swap.
    ///
    /// The axis mapping is not assumed. The FBX is exported Y-up with the model's front on
    /// +Z, so a part's position as imported is the truth, and the chain below is built from
    /// the differences between those positions rather than from the briefs' numbers
    /// re-derived by hand. PlaceholderImportTests asserts that what lands matches the brief.
    /// </summary>
    public sealed class ModelLibrary
    {
        public const string ResourceFolder = "Models";

        private readonly Dictionary<string, GameObject> cache = new();

        /// <summary>The imported asset for an id, or null if it is not in Resources yet.</summary>
        public GameObject Source(string assetId)
        {
            if (cache.TryGetValue(assetId, out GameObject cached)) return cached;
            GameObject loaded = Resources.Load<GameObject>($"{ResourceFolder}/{assetId}");
            cache[assetId] = loaded;
            return loaded;
        }

        /// <summary>A fresh instance of an asset, parented to `parent`.</summary>
        public GameObject Instantiate(string assetId, Transform parent, string name = null)
        {
            GameObject source = Source(assetId);
            GameObject instance = source != null
                ? Object.Instantiate(source, parent)
                : new GameObject(name ?? assetId);
            if (source == null) instance.transform.SetParent(parent, false);
            instance.name = name ?? assetId;
            instance.transform.localPosition = Vector3.zero;
            instance.transform.localRotation = Quaternion.identity;
            return instance;
        }

        /// <summary>A named descendant, or null. Part names come straight from the briefs.</summary>
        public static Transform Part(GameObject instance, string partName)
        {
            foreach (Transform t in instance.GetComponentsInChildren<Transform>(true))
                if (t.name == partName) return t;
            return null;
        }

        /// <summary>
        /// Re-hangs `child` under `parent` keeping its world position, which turns a flat
        /// FBX of parts at their sockets into a chain that rotates about those sockets.
        /// </summary>
        public static void Chain(Transform parent, Transform child)
        {
            Vector3 world = child.position;
            Quaternion rotation = child.rotation;
            child.SetParent(parent, false);
            child.position = world;
            child.rotation = rotation;
        }

        /// <summary>World-space size of everything under an instance.</summary>
        public static Bounds WorldBounds(GameObject instance)
        {
            Renderer[] renderers = instance.GetComponentsInChildren<Renderer>(true);
            if (renderers.Length == 0) return new Bounds(instance.transform.position, Vector3.zero);
            Bounds bounds = renderers[0].bounds;
            for (int i = 1; i < renderers.Length; i++) bounds.Encapsulate(renderers[i].bounds);
            return bounds;
        }
    }
}
